--[[
    NearbySpy_Zones.lua — имя зоны -> uiMapID, сгенерировано скриптом.

    НЕ ПРАВИТЬ РУКАМИ: файл пересобирается командой
        python3 games/wow/scripts/gen_zones.py --build 1.60.1.71037
    Источник — DB2 билда (1.60.1.71037): UiMap + AreaTable +
    UiMapAssignment + цепочка ParentAreaID, локали: 10 (en, zh, ru, de, fr,
    ko, es, es-MX, pt, it).

    Зачем таблица: `/who` отдаёт зону только текстом на языке клиента, а
    «имя -> id» клиент не умеет ни в одной функции C_Map. Без неё текстовые
    зоны из /who оставались без zoneId, и такие записи нельзя было показать
    на языке интерфейса.

    Ключи — в нижнем регистре (сравнение без учёта регистра). Записей:
    7749 (600 имён карт + 7356 подлокаций).
--]]

